/* 2K13 Association: real NBA regular season schedules, 2003-04 through 2025-26.
   Source: Basketball-Reference monthly schedule pages (NBA_YYYY_games-month.html), regular season only.
   Includes the real short seasons: 2011-12 (the lockout: 66 games from Christmas Day), 2019-20 (games through the March 11 suspension, then the bubble
   seeding games to August 14, 63 to 67 games per team) and 2020-21 (72 games). Play-in, playoff and
   NBA Cup championship games are left out (the Cup final does not count in the standings; the Cup
   group and knockout games do and are included as normal games).
   2012-13: the April 16, 2013 Pacers at Celtics game, cancelled after the Boston Marathon bombing and
   never made up, is included and flagged "cancelled" (BOS and IND played 81 games).

   Shape (compact):
     window.SCHEDULES_TEAMS = ["ATL", "BKN", ...]  30 game abbreviations, index 0 to 29
     window.SCHEDULES = { 2013: "<string>", ..., 2026: "<string>" }  keyed by season-ending year
   Each string is "YYYYMMDD" (opening night) followed by 4 characters per game:
     chars 1-2: day offset from opening night in base 36 (0-9a-z)
     char 3: home team index, char 4: away team index, as "ABCDEFGHIJKLMNOPQRSTUVWXYZabcd"[index]
   then optionally "~" and more 4-character games that were scheduled but cancelled (not played).
   Abbreviations are the game's own and stay the same through rebrands: BBRef BRK is BKN, CHO is CHA,
   NOP is NOH, PHO is PHX. Seattle (SEA, through 2007-08) uses OKC's slot; 2003-04 has no CHA games.

   window.SCHEDULES_GET(year) decodes one season into an array sorted by date:
     [ ["2012-10-30", "CLE", "WAS"], ... ]  each [date YYYY-MM-DD, home, away]
     a cancelled game has a 4th element: ["2013-04-16", "BOS", "IND", "cancelled"]
   It returns a fresh array on every call, or null for a year with no real schedule (generate one). */
(function (W) {
  var TEAMS = "ATL BKN BOS CHA CHI CLE DAL DEN DET GSW HOU IND LAC LAL MEM MIA MIL MIN NOH NYK OKC ORL PHI PHX POR SAC SAS TOR UTA WAS".split(" ");
  var DATA = {
    2004: "",
    2005: "",
    2006: "",
    2007: "",
    2008: "",
    2009: "",
    2010: "",
    2011: "",
    2012: "",
    2013: "~4oCL",
    2014: "",
    2015: "",
    2016: "",
    2017: "",
    2018: "",
    2019: "",
    2020: "",
    2021: "",
    2022: "",
    2023: "",
    2024: "",
    2025: "",
    2026: ""
  };
  var ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcd";
  function pad(n) { return n < 10 ? "0" + n : "" + n; }
  function get(year) {
    var s = DATA[year];
    if (!s) return null;
    var t0 = Date.UTC(+s.slice(0, 4), +s.slice(4, 6) - 1, +s.slice(6, 8));
    var out = [], cancelled = false, dates = {};
    // the SuperSonics play in OKC's slot until they move in 2008-09
    var T = year <= 2008 ? TEAMS.map(function (a) { return a === "OKC" ? "SEA" : a; }) : TEAMS;
    for (var i = 8; i < s.length; i += 4) {
      if (s.charAt(i) === "~") { cancelled = true; i -= 3; continue; }
      var off = parseInt(s.slice(i, i + 2), 36);
      var date = dates[off];
      if (!date) {
        var d = new Date(t0 + off * 86400000);
        date = dates[off] = d.getUTCFullYear() + "-" + pad(d.getUTCMonth() + 1) + "-" + pad(d.getUTCDate());
      }
      var g = [date, T[ALPHA.indexOf(s.charAt(i + 2))], T[ALPHA.indexOf(s.charAt(i + 3))]];
      if (cancelled) g.push("cancelled");
      out.push(g);
    }
    // stable sort by date (cancelled games join their date)
    out = out.map(function (g, k) { return [g, k]; })
      .sort(function (a, b) { return a[0][0] < b[0][0] ? -1 : a[0][0] > b[0][0] ? 1 : a[1] - b[1]; })
      .map(function (p) { return p[0]; });
    return out;
  }
  W.SCHEDULES_TEAMS = TEAMS;
  W.SCHEDULES = DATA;
  W.SCHEDULES_GET = get;
  if (typeof module !== "undefined") module.exports = { SCHEDULES: DATA, SCHEDULES_TEAMS: TEAMS, SCHEDULES_GET: get };
})(typeof window !== "undefined" ? window : this);
